/**
 * seed-user.js -- Generated by Claude
 *
 * Dev-only helper to fill a user's vault (jobs, education, projects,
 * optionally a resume) with realistic dummy data, so you're not
 * hand-typing test records every time.
 *
 * Usage:
 *   node seed-user.js --email test@test.com
 *   node seed-user.js --email test@test.com --create            (create the user if it doesn't exist)
 *   node seed-user.js --email test@test.com --create --password mypassword
 *   node seed-user.js --email test@test.com --clear              (wipe that user's existing jobs/education/projects first)
 *   node seed-user.js --email test@test.com --clear --create
 *
 * Notes:
 *   - Looks up the user by email in tblUsers. If not found:
 *       - with --create: registers a new user (bcrypt-hashed password, default "password123")
 *       - without --create: exits with an error so you don't accidentally seed the wrong thing
 *   - Uses the SAME db path logic as server.js (project root database.db when not
 *     running under Electron). If you're testing the packaged Electron app instead,
 *     point --db at the userData database.db, e.g.:
 *       node seed-user.js --email test@test.com --db "/path/to/database.db"
 *   - Safe to run repeatedly; --clear only deletes jobs/education/projects/resumes
 *     for THAT user, never touches other users or the users table itself.
 */

const path = require('path')
const sqlite3 = require('sqlite3')
const bcrypt = require('bcrypt')
const { v4: uuidv4 } = require('uuid')

// --- tiny arg parser ---
function parseArgs(argv) {
    const args = { create: false, clear: false }
    for (let i = 0; i < argv.length; i++) {
        const a = argv[i]
        if (a === '--email') args.email = argv[++i]
        else if (a === '--password') args.password = argv[++i]
        else if (a === '--db') args.db = argv[++i]
        else if (a === '--create') args.create = true
        else if (a === '--clear') args.clear = true
        else if (a === '--help' || a === '-h') args.help = true
    }
    return args
}

const args = parseArgs(process.argv.slice(2))

if (args.help || !args.email) {
    console.log(`
Usage: node seed-user.js --email <email> [--create] [--password <pw>] [--clear] [--db <path>]

  --email       Required. The user to seed dummy data for.
  --create      Create the user if they don't already exist.
  --password    Password to use when creating the user (default: "password123").
  --clear       Delete this user's existing jobs/education/projects/resumes before seeding.
  --db          Path to database.db (default: same path server.js uses in non-Electron mode).
`)
    process.exit(args.help ? 0 : 1)
}

const dbPath = args.db || path.join(__dirname, 'database.db')
console.log(`Using database: ${dbPath}`)

const db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
        console.error(`Could not open database: ${err.message}`)
        process.exit(1)
    }
})

// promisified helpers
const run = (sql, params = []) => new Promise((resolve, reject) => {
    db.run(sql, params, function (err) { err ? reject(err) : resolve(this) })
})
const get = (sql, params = []) => new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => err ? reject(err) : resolve(row))
})

// --- dummy data generators ---

