async function findOrCreateUser(email) {
    let user = await get('SELECT id, full_name FROM tblUsers WHERE email = ?', [email])
    if (user) {
        console.log(`Found existing user: ${email} (id: ${user.id})`)
        return user
    }

    if (!args.create) {
        console.error(`No user found with email "${email}". Re-run with --create to make one, or register them in the app first.`)
        process.exit(1)
    }

    const password = args.password || 'password123'
    const userId = uuidv4()
    const passwordHash = bcrypt.hashSync(password, 12)

    await run('INSERT INTO tblUsers (id, email, password_hash) VALUES (?, ?, ?)', [userId, email, passwordHash])
    console.log(`Created new user: ${email} (id: ${userId}, password: ${password})`)
    return { id: userId, full_name: null }
}

async function fillProfile(userId) {
    await run(
        `UPDATE tblUsers SET full_name = ?, skills = ?, phone = ?, linkedin_url = ?, github_url = ?, summary = ? WHERE id = ?`,
        [DUMMY_PROFILE.full_name, DUMMY_PROFILE.skills, DUMMY_PROFILE.phone, DUMMY_PROFILE.linkedin_url, DUMMY_PROFILE.github_url, DUMMY_PROFILE.summary, userId]
    )
    console.log('Filled profile fields.')
}

async function clearExistingData(userId) {
    await run('DELETE FROM tblJobs WHERE user_id = ?', [userId])
    await run('DELETE FROM tblEducation WHERE user_id = ?', [userId])
    await run('DELETE FROM tblProjects WHERE user_id = ?', [userId])
    await run('DELETE FROM tblResumes WHERE user_id = ?', [userId])
    console.log('Cleared existing jobs/education/projects/resumes for this user.')
}

async function seedJobs(userId) {
    for (const job of DUMMY_JOBS) {
        await run(
            `INSERT INTO tblJobs (id, user_id, company, location, role, start_date, end_date, description) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            [uuidv4(), userId, job.company, job.location, job.role, job.start_date, job.end_date, job.description]
        )
    }
    console.log(`Inserted ${DUMMY_JOBS.length} jobs.`)
}

async function seedEducation(userId) {
    for (const edu of DUMMY_EDUCATION) {
        await run(
            `INSERT INTO tblEducation (id, user_id, school_name, degree, major, minor, gpa, location, start_date, end_date, description) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [uuidv4(), userId, edu.school_name, edu.degree, edu.major, edu.minor, edu.gpa, edu.location, edu.start_date, edu.end_date, edu.description]
        )
    }
    console.log(`Inserted ${DUMMY_EDUCATION.length} education record(s).`)
}

async function seedProjects(userId) {
    for (const proj of DUMMY_PROJECTS) {
        await run(
            `INSERT INTO tblProjects (id, user_id, title, description, tech_stack, link, proj_date) VALUES (?, ?, ?, ?, ?, ?, ?)`,
            [uuidv4(), userId, proj.title, proj.description, proj.tech_stack, proj.link, proj.proj_date]
        )
    }
    console.log(`Inserted ${DUMMY_PROJECTS.length} project(s).`)
}

async function main() {
    try {
        const user = await findOrCreateUser(args.email)

        if (args.clear) {
            await clearExistingData(user.id)
        }

        await fillProfile(user.id)
        await seedJobs(user.id)
        await seedEducation(user.id)
        await seedProjects(user.id)

        console.log(`\nDone. "${args.email}" now has a full dummy vault (profile, ${DUMMY_JOBS.length} jobs, ${DUMMY_EDUCATION.length} education, ${DUMMY_PROJECTS.length} projects).`)
    } catch (err) {
        console.error('Seeding failed:', err)
        process.exitCode = 1
    } finally {
        db.close()
    }
}

main()